{
  "resource": "eventPortal",
  "subResource": "event",
  "action": "create",
  "apiToken": "{{apiToken}}",
  "payload": {
    "name": "OrderCreated",
    "domainId": "{{domainId}}",
    "description": "Fired when a new order is placed"
  }
}

{
  "resource": "fullProvision",
  "action": "provision",
  "apiToken": "{{apiToken}}",
  "skipEventPortal": false,
  "skipCluster": false,
  "payload": {
    "service": {
      "serviceId": "",
      "name": "svc-nz-dev",
      "datacenterId": "aws-ap-southeast-2a",
      "serviceTypeId": "enterprise",
      "serviceClassId": "enterprise-250-nano"
    },
    "eventPortal": {
      "domainName": "OrderDomain-NZ",
      "domainDescription": "NZ order domain",
      "schemas": [
        {
          "name": "OrderSchema",
          "type": "jsonSchema",
          "version": "1.0.0",
          "description": "Order schema",
          "content": { "type": "object", "properties": { "orderId": { "type": "string" } } }
        }
      ],
      "events": [
        {
          "name": "OrderCreated",
          "description": "Order created event",
          "topic": "order/{orderId}/created",
          "version": "1.0.0",
          "schemaRef": "OrderSchema"
        }
      ],
      "applications": [
        {
          "name": "OrderService",
          "type": "standard",
          "description": "Order service",
          "version": "1.0.0",
          "produces": ["OrderCreated"],
          "consumes": []
        }
      ]
    },
    "clusterManagement": {
      "vpnName": "",
      "clientProfiles": [{ "name": "app-profile" }],
      "aclProfiles": [{ "name": "app-acl", "publishDefault": "allow", "subscribeDefault": "allow", "publishExceptions": [], "subscribeExceptions": [] }],
      "clientUsernames": [{ "name": "app-user", "password": "App@12345", "clientProfile": "app-profile", "aclProfile": "app-acl", "enabled": true }],
      "queues": [{ "name": "ORDER.Q", "accessType": "exclusive", "owner": "app-user", "subscriptions": ["order/>"] }],
      "restDeliveryPoints": []
    }
  }
}
